+        return ClusterState.builder(new ClusterName("test"))
+            .metadata(metadataBuilder.indices(indices).transientSettings(nodeSettings).build())
+            .blocks(new ClusterBlocks.Builder().build())
+            .nodes(nodes)
+            .routingTable(routingTableBuilder)
+            .build();
+    }
